const createRetailerOrderItemHandler = (
  draft_id,
  quantity,
  wholesaler_receipt
) => {
  let retailerOrderItem = null;
  let discount_quantity = 0;
  let discount_amount = 0;

  let item_tax = 0;
  let unit_of_issue = "PIECE";
  if (wholesaler_receipt.product_details.is_vatable) {
    item_tax =
      wholesaler_receipt.pack_selling_price *
      0.16 *
      wholesaler_receipt.quantity_issued;
  }

  let items_price = wholesaler_receipt.pack_selling_price * quantity;

  if (wholesaler_receipt.distributor_price_discount) {
    discount_amount = wholesaler_receipt.distributor_price_discount * quantity;
  }

  //Calculate quantity discount
  if (
    wholesaler_receipt.wholesaler_quantity_discount &&
    wholesaler_receipt.wholesaler_quantity_discount_details
  ) {
    //Calculate discount quantity
    discount_quantity =
      parseInt(
        wholesaler_receipt.quantity_issued /
        wholesaler_receipt.wholesaler_quantity_discount_details.limit_quantity
      ) *
      wholesaler_receipt.wholesaler_quantity_discount_details.awarded_quantity;
    //Add discount quantity to purchased quantity to get total amount
  }

  retailerOrderItem = new RetailerOrderItem(
    wholesaler_receipt.id,
    draft_id,
    unit_of_issue = "PIECE",
    wholesaler_receipt.product_details.id,
    wholesaler_receipt.product_details.title,
    wholesaler_receipt.product_details.units_per_pack,
    wholesaler_receipt.pack_selling_price,
    wholesaler_receipt.batch ? wholesaler_receipt.batch : "N/A",
    wholesaler_receipt.id,
    quantity,
    discount_quantity,
    quantity + discount_quantity,
    items_price,
    discount_amount,
    item_tax,
    items_price - discount_amount,
    items_price - discount_amount + item_tax,
    wholesaler_receipt.product_details.images &&
      wholesaler_receipt.product_details.images.length > 0
      ? wholesaler_receipt.product_details.images[0].image
      : ""
  );

  return retailerOrderItem;
};

const createCustomerOrderItemHandler = (payload, item) => {
  let customerOrderItem = null;
  let discount_amount = 0;
  let item_price_total = 0;
  let item_net_price = 0;

  //Calculate  discount quantity
  let total_quantity = 0;
  let discount_quantity = 0;
  if (item.quantity_discount && item.quantity_discount_details) {
    //Calculate discount quantity
    discount_quantity =
      parseInt(
        payload.purchased_quantity /
        item.quantity_discount_details.limit_quantity
      ) * item.quantity_discount_details.awarded_quantity;
    //Add discount quantity to purchased quantity to get total amount
  }

  //Calculate price discount
  if (item.unit_price_discount) {
    discount_amount = item.unit_price_discount * payload.purchased_quantity;
  }

  total_quantity = parseInt(discount_quantity) + parseInt(payload.purchased_quantity);

  item_price_total = item.unit_selling_price * payload.purchased_quantity;
  console.log("ssdcscfgvdhbjnkm", payload);
  item_net_price = item_price_total - discount_amount;

  customerOrderItem = new CustomerOrderItem(
    item.id,
    payload.draft_id,
    item.product.preparation ? item.product.preparation : "",
    item.product.preparation_details
      ? item.product.preparation_details.title
      : "",
    item.product,
    item.product_details.title,
    item.product_details.units_per_pack,
    item.pack_selling_price,
    item.unit_selling_price,
    item.batch,
    item.id,
    payload.purchased_quantity,
    discount_quantity,
    payload.purchased_quantity + discount_quantity,
    item.unit_selling_price,
    item.unit_selling_price * payload.purchased_quantity,
    item.unit_price_discount,
    item.unit_price_discount * payload.purchased_quantity,
    item.item_tax,
    item.item_tax * payload.purchased_quantity,
    item.unit_selling_price - item.unit_price_discount,
    (item.unit_selling_price - item.unit_price_discount) *
    payload.purchased_quantity,
    item.product_details.images.length
      ? item.product_details.images[0].image
      : ""
  );

  return customerOrderItem;
};

const createIndentItem = (remotedata, payload) => {
  let discount_quantity = 0;

  //Calculate quantity discount: additional units to be issued as discout
  if (remotedata.wholesaler_quantity_discount) {
    const limit_quantity =
      remotedata.wholesaler_quantity_discount_details.limit_quantity;
    const awarded_quantity =
      remotedata.wholesaler_quantity_discount_details.awarded_quantity;
    discount_quantity = Math.floor(
      (payload.payload.purchased_quantity / limit_quantity) * awarded_quantity
    );
  }

  //Calculate VAT

  let item_for_indent = new RetailerIndentItem(
    null,
    null,
    remotedata.entity,
    remotedata.entity_title,
    payload.payload.wholesaler_receipt,
    remotedata.product_title,
    remotedata.preparation,
    remotedata.preparation_title,
    remotedata.manufacturer,
    remotedata.manufacturer_title,
    payload.payload.purchased_quantity,
    discount_quantity,
    parseFloat(remotedata.pack_selling_price),
    parseFloat(
      remotedata.pack_selling_price * payload.payload.purchased_quantity
    ),
    parseFloat(remotedata.price_discount),
    parseFloat(remotedata.price_discount * payload.payload.purchased_quantity),
    parseFloat(remotedata.net_price),
    remotedata.net_price * payload.payload.purchased_quantity,
    payload.payload.owner_id,
    remotedata.manufacture_date,
    remotedata.expiry_date,
    remotedata.image ? remotedata.image.image : ""
  );

  return item_for_indent;
};

const transformRetailerReceipts = (filteredData) => {
  let data = [];
  if (filteredData) {
    filteredData.map((i) => {
      data.push(
        new RetailerReceipt(
          i.id,
          i.product_details.title,
          i.product_details && i.product_details.preparation ? true : false,
          i.received_from,
          i.received_from_title,
          i.product_details ? i.product_details.id : "",
          i.product_details ? i.product_details.title : "N/A",
          i.product_details && i.product_details.preparation
            ? i.product_details.preparation
            : "",
          i.product_details && i.product_details.preparation_details
            ? i.product_details.preparation_details.title
            : null,
          i.manufacturer,
          i.product_details.manufacturer_details
            ? i.product_details.manufacturer_details.title
            : "",
          i.product_details.category,
          i.product_details.category_details
            ? i.product_details.category_details.title
            : "",
          i.product.sub_category,
          i.product_details.sub_category_details
            ? i.product_details.sub_category_details.title
            : "",
          i.retailer_variation,
          i.retailer_order,
          i.retailer_order_item,
          i.batch ? i.batch : "",
          i.manufacture_date ? i.manufacture_date : "",
          i.expiry_date ? i.expiry_date : "",
          i.pack_buying_price,
          i.pack_selling_price,
          i.unit_buying_price,
          i.unit_selling_price,
          i.pack_quantity,
          i.unit_quantity,
          i.price_discount,
          i.price_discount_details ? i.price_discount_details.title : "None",
          i.quantity_discount,
          i.quantity_discount_details ? i.quantity_discount_details.title : "None",
          i.product_details.units_per_pack,
          i.product_details &&
            i.product_details.images &&
            i.product_details.images.length
            ? i.product_details.images[0].image
            : "https://cdn.pixabay.com/photo/2018/03/22/02/37/background-3249063__340.png"
        )
      );
    });
    return data;
  } else {
    return [];
  }
};

