const saveDraftOrder = (orderDetails) => {
  let orders = [];
  if (localStorage.getItem("draftCustomerOrders")) {
    orders = JSON.parse(localStorage.getItem("draftCustomerOrders"));
  }


  let modifiedOrders = [];

  if (orders.length > 0) {
    const currentOrders = [...orders];
    if (currentOrders.filter(x => x.draft_id === orderDetails.draft_id).length > 0) {
     
      return false
    } else {
      modifiedOrders = [...currentOrders, orderDetails];
     
    }

  } else {
    modifiedOrders = [orderDetails];
  }

  localStorage.removeItem("draftCustomerOrders");
  localStorage.setItem("draftCustomerOrders", JSON.stringify(modifiedOrders));
  return true;
};

const saveDraftOrderItem = (order, order_item) => {
  let orders = [];
  if (localStorage.getItem("draftCustomerOrders")) {
    orders = JSON.parse(localStorage.getItem("draftCustomerOrders"));
  }

 
  const ordersMinusThisOrder = orders.filter(
    (x) => x.draft_id !== order.draft_id
  );


  const currentOrderItems = order.orderItems;

  let updatedOrderItems = [];
  if (currentOrderItems.length > 0) {
    const orderItemsMinusThisItem = currentOrderItems.filter(
      (x) => x.retailer_receipt !== order_item.retailer_receipt
    );

    updatedOrderItems = [...orderItemsMinusThisItem, order_item];

  } else {
    updatedOrderItems = [order_item];
  
  }
  order.orderItems = updatedOrderItems;

  let modifiedOrders = [];

  modifiedOrders = [...ordersMinusThisOrder, order];

  localStorage.removeItem("draftCustomerOrders");
  localStorage.setItem("draftCustomerOrders", JSON.stringify(modifiedOrders));

  return modifiedOrders;
};

