const updateOrderItemDiscount = (
  draft_id,
  counter_discount=0,
  orderItem
) => {
  let modifiedOrders = [];
  let discount_quantity = 0;
  let orders = [];
  if (localStorage.getItem("draftCustomerOrders")) {
    orders = JSON.parse(localStorage.getItem("draftCustomerOrders"));
  }
  //Isolate current order
  const thisOrder = orders.find((x) => x.draft_id === draft_id);


  //Remove order from orders list
  const ordersMinusThisOrder = orders.filter((x) => x.draft_id !== draft_id);


  //Retrieve order item to change
  let thisOrderItem = thisOrder.orderItems.find(
    (x) => x.retailer_receipt === orderItem.retailer_receipt
  );


  const discount_amount=parseFloat(thisOrderItem.item_price *thisOrderItem.purchased_quantity* counter_discount/100);
  //Modify item
  thisOrderItem.unit_of_issue = "PIECE";
  thisOrderItem.item_counter_price_discount = counter_discount;
  thisOrderItem.discounted_counter_selling_price =parseFloat(discount_amount/100*thisOrderItem.unit_selling_price).toFixed(2);
  thisOrderItem.item_counter_price_discount_amount =discount_amount.toFixed(2);

  thisOrderItem.item_net_price_total =
    thisOrderItem.item_price_total - discount_amount;
  //Remove previous instance of this item from order
  const orderItemsMinusThisItem = thisOrder.orderItems.filter(
    (x) => x.retailer_receipt !== orderItem.retailer_receipt
  );
  console.log("orderItemsMinusThisItem", orderItemsMinusThisItem);

  //Merge updated order item with rest
  const updatedOrderItems = [...orderItemsMinusThisItem, thisOrderItem];

  thisOrder.orderItems = updatedOrderItems;

  modifiedOrders = [...ordersMinusThisOrder, thisOrder];

  console.log("modifiedOrders at chanage quantity", modifiedOrders);

  localStorage.removeItem("draftCustomerOrders");
  localStorage.setItem("draftCustomerOrders", JSON.stringify(modifiedOrders));

  return thisOrder;
};

