import React, { useEffect, useState } from "react";
import * as Yup from "yup";

import { useFormik } from "formik";

import { ToastContainer, toast } from "react-toastify";
import { CustomForm, CustomFormItem, CustomInput, CustomSelectReactSelect } from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import { Modal } from "antd";
import { Button } from "@heroui/react";
import { formatKenyaPhoneNumber } from "../../../helpers/utils";

export default function MpesaNumberFormModal({
  openEditModal,
  setopenEditModal,
  mpesaNumber, setmpesaNumber, customerPhone, setcustomerPhone, customerName, setcustomerName, modalTitle
}) {

  const [errors, setErrors] = useState([])
  const formik = useFormik({
    initialValues: {
            mpesa_number: mpesaNumber ? mpesaNumber : '',

        },

    validationSchema: Yup.object({
      mpesa_number: Yup.number().min(1).required().label("Mpesa phone number"),
    }),
    onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])
            setmpesaNumber(formatKenyaPhoneNumber(values.mpesa_number))
      setcustomerName(values.customer_name)
      setcustomerPhone(values.customer_phone)
            setopenEditModal(false)
        },
  });

  useEffect(() => {
    console.log("errors", formik.errors);
  }, []);

  const { currentColor, dangerColor } = useStateContext();

  const handleOk = () => {
    setopenEditModal(false);
  };
  const handleCancel = () => {
    setopenEditModal(false);
  };

  return (
    <div className="w-full">
      <Modal
        maskClosable={false}
        width={420}
        className="w-full text-center uppercase"
        title={modalTitle}
        open={openEditModal}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <CustomFormItem
            touched={formik.touched.mpesa_number}
            error={formik.errors.mpesa_number}
          >

            <CustomInput
              id="mpesa_number"
              name="mpesa_number"
              autoFocus
              label="Mpesa number"
              placeholder="Enter paying Mpesa number"
              variant="bordered"
              type="text"
              size="large"
              onChange={formik.handleChange}
              onBlur={formik.handleBlur}
              defaultValue={formik.values.mpesa_number}
              value={formik.values.mpesa_number}

            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.customer_name}
            error={formik.errors.customer_name}
          >

            <CustomInput
              id="customer_name"
              name="customer_name"
              autoFocus
              label="Mpesa number"
              placeholder="Enter customer name"
              variant="bordered"
              type="text"
              size="large"
              onChange={formik.handleChange}
              onBlur={formik.handleBlur}
              defaultValue={formik.values.customer_name}
              value={formik.values.customer_name}

            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.customer_phone}
            error={formik.errors.customer_phone}
          >

            <CustomInput
              id="customer_phone"
              name="customer_phone"
              autoFocus
              label="Mpesa number"
              placeholder="Enter customer phone"
              variant="bordered"
              type="text"
              size="large"
              onChange={formik.handleChange}
              onBlur={formik.handleBlur}
              defaultValue={formik.values.customer_phone}
              value={formik.values.customer_phone}

            />


          </CustomFormItem>

          <div className="flex flex-row gap-2 justify-end">
            <Button
              onPress={() => {
                setopenEditModal(false);
                formik.resetForm();
              }}
              style={{ background: dangerColor }}
              type="button"
              fullWidth
              color="primary"
              radius="none"
            >
              Cancel
            </Button>
            <Button
              style={{ background: currentColor, color: "white" }}
              type="submit"
              fullWidth
              color="primary"
              radius="none"
            >
              Save
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
